        <div class="mt-6 space-y-4"><flux:select label="Modèle de message" wire:model.live="selectedTemplate"><flux:select.option value="reminder">Rappel de rendez-vous</flux:select.option><flux:select.option value="promo">Offre promotionnelle</flux:select.option><flux:select.option value="birthday">Joyeux anniversaire</flux:select.option><flux:select.option value="followup">Suivi après visite</flux:select.option><flux:select.option value="new_service">Nouvelle prestation</flux:select.option></flux:select><flux:textarea label="Aperçu du message" wire:model="whatsappMessage" rows="6" /><flux:callout icon="information-circle">Le message s’ouvrira dans WhatsApp et restera modifiable avant l’envoi.</flux:callout><div class="flex justify-end gap-2"> <flux:button wire:click="$set('showWhatsappModal', false)" variant="ghost">Annuler</flux:button>@if($whatsappCustomer?->phone)<flux:button href="https://wa.me/{{ preg_replace('/\D+/', '', $whatsappCustomer->phone) }}?text={{ urlencode($whatsappMessage) }}" target="_blank" variant="primary" color="emerald" icon="paper-airplane">Continuer vers WhatsApp</flux:button>@else<flux:button disabled>Numéro indisponible</flux:button>@endif</div></div>
