    <flux:modal wire:model="showArchiveModal" class="md:w-[30rem]"><span class="flex size-11 items-center justify-center rounded-xl bg-rose-100 text-rose-700 dark:bg-rose-500/10 dark:text-rose-300"><flux:icon.archive-box class="size-5" /></span><flux:heading size="lg" class="mt-4">Archiver ce client ?</flux:heading><flux:text class="mt-2">Le profil disparaîtra de la liste active, mais son historique de ventes sera conservé.</flux:text><div class="mt-6 flex justify-end gap-2"><flux:button wire:click="$set('showArchiveModal', false)" variant="ghost">Annuler</flux:button><flux:button wire:click="confirmArchiveCustomer" variant="danger">Archiver</flux:button></div></flux:modal>
